//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			UPS Data - Riello
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			Netman 208 module - MTCP                                                                                                                                                                                                                                                                                                                           
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-03-26		William Veim			Initial release              
//	1.0.1				2026-04-10		Ruben Byman			Bugfix inverting of communication lost state
//	2.0.0				2025-04-17		William Veim			Rework - Moved modbus configuration to FB 
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
MTCP_Request[0].Enable :=TRUE;
MTCP_Request[0].NodeAdr := 1;
MTCP_Request[0].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
MTCP_Request[0].Read.StartAddressLocal :=0;
MTCP_Request[0].Read.StartAddressRemote := 0;
MTCP_Request[0].Read.Count := 85; 
 
FB_MTCP(Enable:=TRUE, 
				IPAddress:=Cfg_IPAdr, 
				PortNo:=Cfg_PortNo, 
				UpdateRate:=Cfg_UpdateRate, 
				NodeTimeOut:=ADD_TIME(In1:=Cfg_UpdateRate, In2:=Cfg_UpdateRate), 
				Status=>MTCP_Status, 
				RequestCycleDone=>MTCP_ReqCycleDone, 
				RequestCycleTime=>MTCP_ReqCycleTime, 
				Error=>MTCP_Error, 
				ErrorID=>MTCP_ErrorID, 
				ErrorIDEx=>MTCP_ErrorID_Ex, 
				ErrorRequestNO=>MTCP_ErrorRequestNO, 
				ModbusError=>MTCP_ModbusError, 
				Requests:=MTCP_Request, 
				Coils:=MTCP_Coils, 
				DiscreteInputs:=MTCP_DiscreteInputs, 
				InputRegisters:=MTCP_Input, 
				HoldingRegisters:=MTCP_HoldingRegister);
 
(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

Ext_UPS_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

//Communication state
IF MTCP_Request[0].Status.Success AND NOT MTCP_Request[0].Status.Error THEN
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

// Input
Ext_UPS_Data.EXT_Operator.Input_Voltage_L1N :=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[11], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Voltage_L2N := 		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[12], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Voltage_L3N := 		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[13], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Frequency :=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[11], UnvalidValue:=16#FFFF) * 0.1;

// Bypass
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L1N := 		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[21], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L2N := 		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[22], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L3N := 		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[23], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Bypass_Frequency :=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[14], UnvalidValue:=16#FFFF) * 0.1;

// Output
Ext_UPS_Data.EXT_Operator.Output_Voltage_L1N:=  		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[25], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Voltage_L2N:=  		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[26], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Voltage_L3N:=  		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[27], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L1:= 				HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[37], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L2:= 				HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[38], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L3:= 				HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[39], UnvalidValue:=16#FFFF);

//Battery
Ext_UPS_Data.EXT_Operator.Battery_Voltage:=				HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[47], UnvalidValue:=16#FFFF) * 0.1;
Ext_UPS_Data.EXT_Operator.Battery_ChargeLevel:=		HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[51], UnvalidValue:=16#FFFF);

//Common
Ext_UPS_Data.EXT_Operator.Com_Temperature:=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[61], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Com_Nom_ActivePower:=	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[80], UnvalidValue:=16#FFFF) * 0.1;
Ext_UPS_Data.EXT_Operator.Com_Nom_BatteryCap:=	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[83], UnvalidValue:=16#FFFF) * 0.1;
Ext_UPS_Data.EXT_Operator.Com_BatteryCharged:=		TestABit(In:=MTCP_HoldingRegister[0], Pos:=5);
Ext_UPS_Data.EXT_Operator.Com_InputPresent:=			TestABit(In:=MTCP_HoldingRegister[1], Pos:=12);
Ext_UPS_Data.EXT_Operator.Com_NormalOperation:=	TestABit(In:=MTCP_HoldingRegister[0], Pos:=9);
Ext_UPS_Data.EXT_Operator.Com_OutputPowered:=		TestABit(In:=MTCP_HoldingRegister[0], Pos:=15);

// Alarms
Wrk_State[1]:=NOT Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=3);
Wrk_Suffix[2]:='Shutdown active';
Wrk_State[3]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=7);
Wrk_Suffix[3]:='Bypass bad';
Wrk_State[4]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=11);
Wrk_Suffix[4]:='On bypass';
Wrk_State[5]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=12);
Wrk_Suffix[5]:='Battery low';
Wrk_State[6]:=TestABit(In:=MTCP_HoldingRegister[1], Pos:=13);
Wrk_Suffix[6]:='Alarm temperature';
Wrk_State[7]:=TestABit(In:=MTCP_HoldingRegister[1], Pos:=14);
Wrk_Suffix[7]:='Alarm overload';
Wrk_State[8]:=TestABit(In:=MTCP_HoldingRegister[1], Pos:=15);
Wrk_Suffix[8]:='UPS failiure';
Wrk_State[9]:=TestABit(In:=MTCP_HoldingRegister[3], Pos:=15);
Wrk_Suffix[9]:='Communication lost internal';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_UPS_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_UPS_Data.EXT_Engineering, 
						Ext_General:=					Ext_UPS_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= FB_Data_Logic.Sts_AlarmTriggered;
 
 //STRUCTURE
 Ext_UPS_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ConnCab;
 Ext_UPS_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_UPS_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
